@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=DM+Mono:wght@400;500&display=swap');
:root{color-scheme:dark;--ink:#f6eee0;--muted:#a49c93;--red:#ef654e;--gold:#e4b46a;--panel:rgba(17,21,30,.94)}
*{box-sizing:border-box}html,body{width:100%;height:100%;margin:0;background:#10131c;color:var(--ink);font-family:'Barlow Condensed',sans-serif;overflow:hidden;touch-action:none}body{display:grid;place-items:center}#game-shell{position:relative;width:min(100vw,177.7778vh);height:min(100vh,56.25vw);aspect-ratio:16/9;overflow:hidden;background:#10131c;box-shadow:0 20px 90px #0009}canvas{display:block;width:100%;height:100%;image-rendering:pixelated;touch-action:none}.screen{position:absolute;inset:0;display:grid;align-items:center;padding:6% 8%;background:linear-gradient(90deg,rgba(8,11,17,.88),rgba(8,11,17,.48) 56%,rgba(8,11,17,.06)),linear-gradient(0deg,rgba(7,10,15,.55),transparent 40%);opacity:0;pointer-events:none;transition:opacity .35s}.screen.visible{opacity:1;pointer-events:auto}.menu-card{position:relative;max-width:510px;z-index:1}.eyebrow,.menu-foot,.eyebrow{font-family:'DM Mono',monospace;font-size:10px;letter-spacing:.18em;color:#d3a56e}.eyebrow{margin:0 0 17px}.menu-card h1{font-size:clamp(52px,8.5vw,93px);line-height:.77;letter-spacing:-.045em;margin:0 0 22px;font-weight:900;color:#f6eee0;text-shadow:4px 4px 0 #161a23}.menu-card h1 span{font-size:.39em;color:#dfb46f;letter-spacing:.22em;vertical-align:middle}.subtitle{font-size:18px;line-height:1.35;color:#c5beb4;margin:0 0 29px}.menu-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.menu-actions button{height:48px;padding:0 20px;border:1px solid #ffffff20;font-family:'DM Mono',monospace;font-size:11px;letter-spacing:.1em;color:var(--ink);cursor:pointer;transition:transform .15s,background .15s}.menu-actions button:hover{transform:translateY(-2px)}.primary{background:#d85e46;border-color:#ef8068!important;box-shadow:0 7px 22px #9f382e44}.primary b{font-size:18px;margin-left:12px}.secondary{background:#171b26cc}.menu-foot{display:flex;gap:25px;margin-top:38px;color:#8f918f;font-size:9px;letter-spacing:.08em}.menu-mark{position:absolute;right:13%;top:16%;font-size:min(25vw,220px);color:#e69e5b12;font-weight:900;line-height:1}.modal{position:absolute;inset:0;display:none;place-items:center;background:#080b11b8;backdrop-filter:blur(7px);z-index:5}.modal.open{display:grid}.modal-card{width:min(560px,84%);padding:28px 34px;background:linear-gradient(135deg,#1d222d,#11151d);border:1px solid #dcb27755;box-shadow:0 25px 70px #0009}.modal-card h2{margin:0 0 7px;font-size:36px;letter-spacing:.02em}.modal-card p{color:#b6b0a7;font-size:16px}.modal-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:23px}.modal-actions button,.reward-card{font-family:'DM Mono',monospace;cursor:pointer;color:#f6eee0;background:#282c34;border:1px solid #ffffff20;padding:12px 15px;letter-spacing:.05em}.modal-actions button:hover,.reward-card:hover{background:#8c483c}.reward-grid{display:flex;gap:12px;margin:20px 0}.reward-card{flex:1;text-align:left;min-height:110px}.reward-card strong{display:block;color:#e3b46e;margin-bottom:8px}.reward-card small{font-family:'Barlow Condensed',sans-serif;color:#c2bdb5;font-size:14px;letter-spacing:0}.touch-cluster,.stick-zone,#pause-button{display:none}#rotate-hint{display:none}
@media (pointer:coarse){.touch-cluster,.stick-zone{display:flex}#pause-button{display:grid}#game-shell{width:100vw;height:100vh;max-height:100vh;max-width:none;aspect-ratio:auto}.touch-cluster{position:absolute;bottom:5%;right:3.5%;width:31%;height:45%;pointer-events:none}.touch{pointer-events:auto;position:absolute;border:1px solid #e8dfcc66;border-radius:50%;background:#151923b8;color:#f4ead8;font:500 10px 'DM Mono',monospace;letter-spacing:.04em;touch-action:none;box-shadow:0 4px 14px #0005;user-select:none;-webkit-user-select:none;transition:transform .08s,background .08s}.touch.active,.touch:active{transform:scale(.92);background:#c75643dd}.right-cluster .attack{width:66px;height:66px;right:5%;bottom:3%;background:#a84436cc}.right-cluster .heavy{width:60px;height:60px;right:33%;bottom:14%}.right-cluster .jump{width:62px;height:62px;right:6%;top:2%}.right-cluster .dash{width:56px;height:56px;right:35%;bottom:0}.right-cluster .skill{width:54px;height:54px;right:36%;top:4%;font-size:8px}.right-cluster .skill[data-action=skill2]{right:66%;top:33%}.left-cluster{left:2%;right:auto;width:20%;height:38%;bottom:5%}.left-cluster .skill{width:53px;height:53px;left:2%;top:3%;font-size:8px}.left-cluster .defense{width:60px;height:60px;right:1%;bottom:4%;font-size:9px}.stick-zone{position:absolute;left:3%;bottom:4%;width:125px;height:125px;align-items:center;justify-content:center;touch-action:none}.left-cluster{left:3%;bottom:4%;width:125px;height:125px}.left-cluster .skill{left:0;top:-62px}.left-cluster .defense{right:-70px;bottom:-5px}#stick-base{width:94px;height:94px;border:1px solid #e8dfcc55;border-radius:50%;background:#15192380;display:grid;place-items:center}#stick-knob{width:40px;height:40px;border:1px solid #f4ead899;border-radius:50%;background:#c7564380;box-shadow:0 2px 8px #0005;transform:translate(0,0)}#pause-button{position:absolute;display:grid;place-items:center;top:3%;right:3%;width:38px;height:38px;border:1px solid #e8dfcc66;border-radius:50%;background:#11151dcc;color:#f4ead8;font:16px 'DM Mono',monospace;z-index:4}.menu-foot{display:none}.screen{padding:7% 7%}.menu-card{max-width:58%}.menu-card h1{font-size:clamp(42px,8vw,82px)}.subtitle{font-size:15px}.menu-actions button{height:40px}.menu-mark{right:12%;top:12%}}
@media (orientation:portrait) and (pointer:coarse){#rotate-hint{display:grid;position:absolute;inset:0;place-items:center;background:#10131c;color:#f6eee0;font:500 13px 'DM Mono',monospace;letter-spacing:.12em;z-index:20}#game-shell canvas,#game-shell .screen,#game-shell .modal,#game-shell #touch-controls,#game-shell #pause-button{visibility:hidden}}
@media (max-width:700px){.menu-card{max-width:70%}.menu-card h1{font-size:clamp(38px,9vw,66px)}.subtitle{font-size:13px}.menu-actions{gap:7px}.menu-actions button{padding:0 11px;font-size:9px}}

(() => {
'use strict';
const canvas = document.querySelector('#game');
const ctx = canvas.getContext('2d');
const screen = document.querySelector('#screen');
const modal = document.querySelector('#modal');
const W = 960, H = 540;
ctx.imageSmoothingEnabled = false;
let last = 0, time = 0, cameraX = 0, screenMode = 'title', modalOpen = false;
let worldWidth = 2380, roomName = 'CINDER PASS';
const keys = new Set(), held = {block:false};
const input = {move:0, jump:false, attack:false, heavy:false, dash:false, block:false, skill1:false, skill2:false};
let player, enemies=[], particles=[], projectiles=[], floaters=[], wave=1, runCoins=0, killCount=0, difficulty='NORMAL';
let shake=0, flash=0, combo=0, comboTimer=0, message='', messageTimer=0;
const saved = loadSave();
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const rnd=(a,b)=>a+Math.random()*(b-a);
const rect=(x,y,w,h,c)=>{ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))};
const text=(s,x,y,size=12,color='#f7eddd',align='left',font='Barlow Condensed')=>{ctx.fillStyle=color;ctx.font=`600 ${size}px '${font}'`;ctx.textAlign=align;ctx.fillText(s,x,y)};
function loadSave(){try{return JSON.parse(localStorage.getItem('ashesSave'))||{shards:0,rank:1,damage:0,health:0,controls:{opacity:.82,scale:1}}}catch{return {shards:0,rank:1,damage:0,health:0,controls:{opacity:.82,scale:1}}}}
function persist(){localStorage.setItem('ashesSave',JSON.stringify(saved))}
function freshPlayer(){return {x:116,y:0,vx:0,vy:0,w:28,h:46,face:1,hp:100+saved.health*10,maxHp:100+saved.health*10,chakra:100,maxChakra:100,stamina:100,maxStamina:100,onGround:false,coyote:0,jumpBuffer:0,jumpHeld:false,attackTimer:0,attackType:'',attackHit:false,comboStep:0,comboWindow:0,dashTimer:0,dashCooldown:0,dashDir:1,invuln:0,guard:false,parryTimer:0,guardBreak:0,hitstun:0,skillCooldown:0,skill2Cooldown:0,charging:false,dead:false,anim:0,airAttack:false,killFlash:0}}
function initRun(){player=freshPlayer();enemies=[];particles=[];projectiles=[];floaters=[];wave=1;runCoins=0;killCount=0;cameraX=0;screenMode='play';modalOpen=false;modal.classList.remove('open');screen.classList.remove('visible');spawnWave();message='CLEAR THE PASS';messageTimer=2.2;}
function spawnWave(){let specs=wave===1?[['scout',740],['blade',1070],['scout',1450]]:wave===2?[['blade',690],['caster',1120],['assassin',1590]]:[['boss',1660]];for(const [type,x] of specs)enemies.push(makeEnemy(type,x));}
function makeEnemy(type,x){const defs={scout:{hp:30,w:27,h:42,speed:80,range:58,damage:9,cd:1.55,color:'#708276',name:'ROGUE SCOUT'},blade:{hp:48,w:32,h:48,speed:62,range:66,damage:13,cd:1.8,color:'#9b5548',name:'SWORD RUNNER'},assassin:{hp:40,w:27,h:44,speed:126,range:55,damage:11,cd:1.25,color:'#765d9c',name:'ASH ASSASSIN'},caster:{hp:38,w:28,h:45,speed:42,range:240,damage:12,cd:2,color:'#497e9a',name:'SEAL CASTER'},boss:{hp:260,w:76,h:94,speed:52,range:120,damage:22,cd:2.05,color:'#ae493d',name:'THE HOLLOW WARDEN'}};let d=defs[type],scale=difficulty==='EASY'?.75:difficulty==='HARD'?1.4:difficulty==='NIGHTMARE'?1.9:difficulty==='LEGENDARY'?2.5:1;return {...d,type,x,y:GROUND-d.h,vx:0,hp:d.hp*scale,maxHp:d.hp*scale,face:-1,cd:rnd(.4,1.3),state:'approach',tell:0,attackTimer:0,hitstun:0,flash:0,dead:false,hitBy:0,phase:0}}
const GROUND=430;

//__PART2__
})();

