const CLANS=[
 {name:'Uchiha',rarity:'Legendary',passive:'Read intent early; +12% fire damage and counter damage.',exclusive:['Sharingan','Fire Style: Great Fireball','Phoenix Flower']},
 {name:'Hyuga',rarity:'Epic',passive:'+15% precision; nearby attackers are revealed sooner.',exclusive:['Byakugan','Gentle Fist','Eight Trigrams Rotation']},
 {name:'Uzumaki',rarity:'Rare',passive:'+30 maximum chakra and +10% vitality.',exclusive:['Chakra Chains','Sealing Art']},
 {name:'Senju',rarity:'Rare',passive:'+15 maximum health; +10% nature technique strength.',exclusive:['Wood Release','Vitality Bloom']},
 {name:'Kaguya',rarity:'Uncommon',passive:'+10% melee damage; bone techniques stagger armor.',exclusive:['Bone Armor','Bone Lance']},
 {name:'Nara',rarity:'Common',passive:'Shadow traps last longer and slow enemies.',exclusive:['Shadow Possession','Shadow Stitching']},
 {name:'Yamanaka',rarity:'Common',passive:'Mind disruption leaves enemies vulnerable longer.',exclusive:['Mind Transfer','Mind Disruption']},
 {name:'Akimichi',rarity:'Common',passive:'+12% heavy attack damage and knockback.',exclusive:['Partial Expansion','Human Boulder']},
 {name:'Aburame',rarity:'Common',passive:'Insects track distant foes and drain chakra.',exclusive:['Insect Swarm','Insect Guard']},
 {name:'Inuzuka',rarity:'Common',passive:'+10% movement speed; companion strikes mark targets.',exclusive:['Fang Over Fang','Dynamic Marking']},
 {name:'Lee/Guy Lineage',rarity:'Uncommon',passive:'Strong Fist style; gates unlock progressively.',exclusive:['Strong Fist','Dynamic Entry','Front Lotus','Eight Gates']}
];
const ELEMENTS=['Fire','Wind','Lightning','Earth','Water','Yin','Yang'];
const BLOODLINES=[['Wood Release','Senju'],['Ice Release'],['Lava Release'],['Boil Release'],['Storm Release'],['Magnet Release'],['Explosion Release'],['Scorch Release'],['Dust Release']];
const BLOODLINE_DETAILS={
 'Wood Release':'Bind foes with living timber; roots control lanes.','Ice Release':'Create sharp barriers and freeze enemy movement.','Lava Release':'Leave dangerous molten zones and heavy bursts.','Boil Release':'Trade chakra for explosive pressure and speed.','Storm Release':'Guide piercing beams through multiple targets.','Magnet Release':'Pull metal weapons and pin enemies in place.','Explosion Release':'Plant delayed blasts for area denial.','Scorch Release':'Burn targets over time with concentrated heat.','Dust Release':'Charge a narrow, devastating disintegration beam.'};
const DOJUTSU_BY_CLAN={Uchiha:['Sharingan','Three-Tomoe Sharingan','Mangekyou Sharingan','Eternal Mangekyou Sharingan'],Hyuga:['Byakugan']};
const RARITIES=[['Common',.50],['Uncommon',.25],['Rare',.15],['Epic',.07],['Legendary',.025],['Mythical',.005]];
const rarityColor={Common:'#aaa99f',Uncommon:'#68c995',Rare:'#70b8ec',Epic:'#bc86ff',Legendary:'#f2bd61',Mythical:'#ff738a'};
const ELEMENT_MOVES={
 Fire:[['Fireball Technique','A focused burning projectile.',25,15,4,'projectile'],['Phoenix Flower Technique','A fan of fast ember shots.',8,20,6,'volley'],['Great Fireball Technique','A slow, heavy blast with broad impact.',45,35,10,'blast'],['Flame Wall','Raise a short-lived burning barrier.',18,24,8,'wall'],['Dragon Flame Technique','A rushing flame line that pierces foes.',38,30,9,'pierce']],
 Wind:[['Wind Blade','A quick slicing crescent.',22,14,4,'blade'],['Vacuum Wave','A long-range cutting wave.',30,22,7,'wave'],['Wind Bullet','A compact piercing shot.',18,12,3,'projectile'],['Gale Burst','A close knockback gust.',24,20,6,'burst'],['Great Wind Cutter','A broad, high-impact air blade.',42,34,10,'cutter']],
 Lightning:[['Lightning Blade','A fast forward thrust.',45,30,8,'dash'],['Chidori','A piercing charge with brief invulnerability.',55,35,9,'charge'],['Lightning Field','Shock nearby enemies over time.',9,24,8,'field'],['Lightning Projectile','A quick piercing bolt.',24,17,5,'projectile'],['Thunder Burst','An explosive close-range stun.',34,28,8,'burst']],
 Earth:[['Earth Wall','Raise a guard that absorbs a hit.',0,18,8,'guard'],['Earth Spear','Launch a heavy ground spike.',32,20,6,'spike'],['Earth Dragon','Send a stagger wave along the floor.',36,28,9,'wave'],['Ground Spike','Strike a target underfoot.',26,16,5,'trap'],['Earth Prison','Root a nearby enemy briefly.',12,26,10,'bind']],
 Water:[['Water Bullet','A quick ranged stream.',20,14,4,'projectile'],['Water Dragon','A heavy traveling current.',40,32,9,'wave'],['Water Prison','Hold a foe in a water sphere.',10,24,8,'bind'],['Water Wave','Push a wide wave forward.',28,22,6,'wave'],['Water Shark Projectile','A tracking bite with strong reach.',34,28,8,'seeker']],
 Yin:[['False Surroundings','Confuse nearby foes and interrupt tells.',8,18,7,'illusion'],['Shadow Pulse','A short-range shadow strike.',22,20,6,'burst'],['Night Veil','Briefly mask your position.',0,22,9,'veil'],['Mind Lance','A focused mind-piercing shot.',29,24,7,'pierce'],['Dream Snare','Slow enemies in a marked area.',12,30,10,'bind']],
 Yang:[['Vitality Surge','Restore a little health and boost force.',0,25,9,'heal'],['Pulse Strike','An enhanced melee hit.',28,18,5,'melee'],['Renewing Breath','Recover stamina and interrupt nearby foes.',0,20,8,'support'],['Sunstep','A swift empowered lunge.',24,20,6,'dash'],['Life Guard','Create a brief damage-reducing aura.',0,32,11,'guard']]
};
const ADVANCED_MOVES=Object.fromEntries(Object.entries(BLOODLINE_DETAILS).map(([name,description],i)=>[name,{name,description,damage:26+i*2,ch:24+i%3*3,cooldown:8+i%3,range:260,startup:.3,active:.25,recovery:.4,hitbox:'element-specific',animation:'bloodline technique',vfx:name.toLowerCase(),upgradePath:'Technique Mastery I → II → III'}]));
function saveProgress(){persist()}
function clanInfo(){return CLANS.find(c=>c.name===saved.clan)}
function movesForElement(element=saved.element||'Fire'){return (ELEMENT_MOVES[element]||ELEMENT_MOVES.Fire).map((m,i)=>({name:m[0],description:m[1],damage:m[2],ch:m[3],cooldown:m[4],range:260,startup:.18+i*.06,active:.16+i*.04,recovery:.25+i*.06,hitbox:m[5],animation:`${element.toLowerCase()} cast ${i+1}`,vfx:`${element.toLowerCase()}-${m[5]}`,upgradePath:`${m[0]} I → II → III`,kind:m[5]}))}
function grantResult(category,result,rarity){let list=saved.obtained[category];if(list.includes(result)){let pay={Common:2,Uncommon:4,Rare:8,Epic:15,Legendary:30,Mythical:60}[rarity];saved.shards+=pay;return {duplicate:true,pay}}
 list.push(result);if(category==='clan')saved.clan=result;
 if(category==='element')saved.element=result;
 if(category==='bloodline')saved.bloodline=result;
 if(category==='dojutsu')saved.dojutsu=result;
 if(category==='bloodline'&&result==='Wood Release'&&saved.clan!=='Senju')return {restricted:true};
 return {duplicate:false,pay:0}}
function rarityRoll(){let n=Math.random();for(const [r,p] of RARITIES){if(n<p)return r;n-=p}return 'Common'}
function weightedPick(list){return list[Math.floor(Math.random()*list.length)]}
function spinPool(category,rarity){if(category==='clan')return CLANS.filter(c=>c.rarity===rarity).map(c=>c.name);
 if(category==='element'){const table={Common:['Fire','Wind','Earth','Water'],Uncommon:['Lightning','Yin','Yang'],Rare:['Lightning','Yin','Yang'],Epic:['Yin','Yang'],Legendary:['Yin','Yang'],Mythical:['Yin','Yang']};return table[rarity]}
 if(category==='bloodline'){const map={Common:['Ice Release','Explosion Release','Magnet Release'],Uncommon:['Lava Release','Boil Release','Scorch Release'],Rare:['Wood Release','Storm Release'],Epic:['Dust Release'],Legendary:['Dust Release','Wood Release'],Mythical:['Dust Release']};return map[rarity].filter(n=>n!=='Wood Release'||saved.clan==='Senju')}
 if(category==='dojutsu'){const allowed=DOJUTSU_BY_CLAN[saved.clan]||[];if(allowed.length===0)return rarity==='Common'?['Enhanced Sight']:[];if(saved.clan==='Uchiha'){const tier={Common:['Sharingan'],Uncommon:['Sharingan'],Rare:['Three-Tomoe Sharingan'],Epic:['Mangekyou Sharingan'],Legendary:['Eternal Mangekyou Sharingan'],Mythical:['Eternal Mangekyou Sharingan']};return tier[rarity].filter(n=>!saved.obtained.dojutsu.includes(n)||rarity==='Common')};return rarity==='Common'?['Byakugan']:rarity==='Rare'?['Byakugan']:[]}
 return []}
function rollSpin(category){let rarity=rarityRoll(),pool=spinPool(category,rarity);if(!pool.length){rarity='Common';pool=spinPool(category,rarity)}if(!pool.length){pool=category==='dojutsu'?['Enhanced Sight']:category==='element'?ELEMENTS:[];rarity='Common'}let result=weightedPick(pool);let outcome=grantResult(category,result,rarity);return {category,rarity,result,...outcome}}
function displayResult(r){let title=r.result;let detail=r.category==='clan'?(CLANS.find(c=>c.name===title)?.passive||'A new identity is recorded.'):r.category==='element'?`${title} affinity · ${movesForElement(title).length} techniques available.`:r.category==='bloodline'?(BLOODLINE_DETAILS[title]||'A heightened visual perception trait.'):`${title} · exclusive ocular progression.`;return `<span style="color:${rarityColor[r.rarity]}">${r.rarity.toUpperCase()}</span><strong>${title}</strong><p>${detail}</p>${r.duplicate?`<p class="compensation">DUPLICATE CONVERTED · +${r.pay} EMBER SHARDS</p>`:''}`}
function showSpinMenu(category='clan'){let names={clan:'CLAN SPINS',element:'ELEMENT SPINS',bloodline:'BLOODLINE SPINS',dojutsu:'DOJUTSU SPINS'};modalOpen=true;modal.classList.add('open');modal.innerHTML=`<div class="modal-card spin-modal"><p class="eyebrow">PERMANENT IDENTITY · SAVED AUTOMATICALLY</p><h2>SCROLL OF FATE</h2><p>Four independent pools. Clan restrictions are enforced; Rinnegan and Bijuu never appear here.</p><div class="spin-tabs">${Object.keys(names).map(k=>`<button data-spin-tab="${k}" class="${category===k?'selected':''}">${names[k]} <b>${saved.spins[k]}</b></button>`).join('')}</div><div class="spin-reveal" id="spin-reveal"><span>CHOOSE A SCROLL</span><strong>${names[category]}</strong><p>Each draw uses its own rarity-weighted result pool.</p></div><div class="spin-controls"><button data-spin-count="1">SPIN ×1</button><button data-spin-count="10">SPIN ×10</button><button data-action="skip-spin">SKIP REVEAL</button><span>EMBER SHARDS <b>${saved.shards}</b></span></div><div class="modal-actions"><button data-action="close">BACK</button></div></div>`;
