function frame(now){let dt=Math.min(.033,(now-last)/1000||0);last=now;if(screenMode==='play'&&!paused&&!modalOpen)update(dt);draw();requestAnimationFrame(frame)}
let comboStep=0;
function showRewards(){const options=[['Sharpened Edge','Permanent · +8% attack damage','damage'],['Vitality Seal','Permanent · +10 maximum health','health'],['Chakra Reservoir','Run · restore 35 chakra','chakra']];modalOpen=true;modal.classList.add('open');modal.innerHTML=`<div class="modal-card"><p class="eyebrow">ROOM ${wave-1} CLEARED</p><h2>CHOOSE YOUR REWARD</h2><p>Your room reward is separate from any special Rinnegan roll.</p><div class="reward-grid">${options.map(o=>`<button class="reward-card" data-reward="${o[2]}"><strong>${o[0]}</strong><small>${o[1]}</small></button>`).join('')}</div><div class="modal-actions"><button data-action="continue">CONTINUE</button></div><div id="special-reward"></div></div>`;modal.querySelectorAll('[data-reward]').forEach(b=>b.onclick=()=>{const r=b.dataset.reward;if(r==='damage')saved.damage++;if(r==='health'){saved.health++;player.maxHp+=10;player.hp+=10}if(r==='chakra')player.chakra=Math.min(player.maxChakra,player.chakra+35);saveProgress();b.disabled=true;b.innerHTML='<strong>SELECTED</strong><small>Added to your build.</small>'});
 // This is an independent 0.5% bonus roll; ordinary reward choices remain intact.
 if(!saved.rinnegan&&Math.random()<0.005){saved.rinnegan=true;saveProgress();const area=modal.querySelector('#special-reward');area.innerHTML='<p class="rinnegan-reveal">✦ MYTHIC REVEAL · RINNEGAN UNLOCKED ✦</p>';}
 modal.querySelector('[data-action=continue]').onclick=()=>{closeModal();spawnWave()}}
function showVictory(){screenMode='victory';modalOpen=true;modal.classList.add('open');modal.innerHTML=`<div class="modal-card"><p class="eyebrow">THE PASS IS QUIET</p><h2>WARDEN DEFEATED</h2><p>Run rewards: ${runCoins} embers · ${killCount} foes defeated. Permanent records remain yours after defeat.</p><div class="modal-actions"><button data-action="home">RETURN TO TITLE</button><button data-action="restart">RUN AGAIN</button></div></div>`;saved.shards+=runCoins;saveProgress();modal.querySelector('[data-action=home]').onclick=showTitle;modal.querySelector('[data-action=restart]').onclick=initRun}
function showDefeat(){modalOpen=true;modal.classList.add('open');modal.innerHTML=`<div class="modal-card"><p class="eyebrow">THE BORDER CLAIMS ANOTHER</p><h2>RUN ENDED</h2><p>Collected ${runCoins} embers. Temporary run bonuses are lost; permanent identity and unlocks are safe.</p><div class="modal-actions"><button data-action="home">RETURN TO TITLE</button><button data-action="restart">TRY AGAIN</button></div></div>`;saved.shards+=runCoins;saveProgress();modal.querySelector('[data-action=home]').onclick=showTitle;modal.querySelector('[data-action=restart]').onclick=initRun}
function showTitle(){screenMode='title';paused=false;modalOpen=false;modal.classList.remove('open');screen.classList.add('visible')}
function showProgression(){const clan=clanInfo();modalOpen=true;modal.classList.add('open');modal.innerHTML=`<div class="modal-card progression-modal"><p class="eyebrow">PERMANENT SHINOBI RECORD</p><h2>IDENTITY & PROGRESSION</h2><div class="progress-columns"><div class="preview-card"><div class="mini-ninja" style="--skin:${saved.identity.skin};--outfit:${saved.identity.outfit};--hair:${saved.identity.hairColor}"></div><strong>${saved.identity.name}</strong><button data-action="customize">CUSTOMIZE</button></div><div><h3>IDENTITY</h3><p>Clan: <b>${saved.clan||'Unawakened'}</b><br>Element: <b>${saved.element||'Unawakened'}</b><br>Bloodline: <b>${saved.bloodline||'None'}</b><br>Dojutsu: <b>${saved.dojutsu||'None'}</b>${saved.rinnegan?'<br>Rinnegan: <b>Unlocked</b>':''}</p><p>${clan?.passive||'Use clan scrolls to discover a permanent lineage.'}</p></div><div><h3>COLLECTION</h3><p>Bijuu cards: ${saved.bijuuCards.join(', ')||'None'}<br>Equipped: ${saved.equippedBijuu||'None'}<br>Strong Fist: ${saved.clan==='Lee/Guy Lineage'?'Available':'Lee/Guy lineage only'}<br>Gates unlocked: ${saved.clan==='Lee/Guy Lineage'?saved.gates:0}/8</p><p>Ember Shards: ${saved.shards}</p><button data-action="bijuu">BIJUU CHALLENGES</button></div></div><div class="modal-actions"><button data-action="spins">OPEN SPINS</button><button data-action="close">BACK</button></div></div>`;modal.querySelector('[data-action=customize]').onclick=showCustomize;modal.querySelector('[data-action=bijuu]').onclick=showBijuuCollection;modal.querySelector('[data-action=spins]').onclick=()=>showSpinMenu();modal.querySelector('[data-action=close]').onclick=closeModal}
function showCustomize(){modalOpen=true;modal.classList.add('open');const id=saved.identity;modal.innerHTML=`<div class="modal-card progression-modal"><p class="eyebrow">CHARACTER CUSTOMIZATION</p><h2>SHAPE YOUR SHINOBI</h2><div class="progress-columns"><div class="preview-card"><div class="mini-ninja" style="--skin:${id.skin};--outfit:${id.outfit};--hair:${id.hairColor}"></div><strong>${id.name}</strong></div><div class="custom-fields"><label>Name <input id="custom-name" maxlength="16" value="${id.name}"></label><label>Hairstyle <select id="custom-hair"><option>Spiked</option><option>Short</option><option>Long</option><option>Wild</option></select></label><label>Hair color <input id="custom-hair-color" type="color" value="${id.hairColor}"></label><label>Skin tone <select id="custom-skin"><option value="#d69a72">Warm</option><option value="#f0c6a0">Light</option><option value="#8c5a43">Deep</option><option value="#bd8667">Olive</option></select></label><label>Outfit <input id="custom-outfit" type="color" value="${id.outfit}"></label><label>Headband <input id="custom-headband" type="checkbox" ${id.headband?'checked':''}></label></div><div><h3>EQUIPPED LOOK</h3><p>Clan and ocular effects update as permanent traits are unlocked. Accessories and weapon skins will expand with progression.</p><p>${saved.clan||'No clan'} · ${saved.dojutsu||'No dojutsu'} · ${saved.equippedBijuu||'No Bijuu'}</p></div></div><div class="modal-actions"><button data-action="save-custom">SAVE LOOK</button><button data-action="progress">BACK</button></div></div>`;modal.querySelector('#custom-hair').value=id.hair;modal.querySelector('#custom-skin').value=id.skin;modal.querySelector('[data-action=save-custom]').onclick=()=>{saved.identity={name:modal.querySelector('#custom-name').value.trim()||'Shinobi',hair:modal.querySelector('#custom-hair').value,hairColor:modal.querySelector('#custom-hair-color').value,skin:modal.querySelector('#custom-skin').value,outfit:modal.querySelector('#custom-outfit').value,headband:modal.querySelector('#custom-headband').checked};saveProgress();showProgression()};modal.querySelector('[data-action=progress]').onclick=showProgression}
const BIJUU=[['Shukaku','Sand burial and sweeping sand waves'],['Matatabi','Blue flame arcs and pouncing fire'],['Isobu','Shell charges and tidal surges'],['Son Goku','Lava punches and seismic stomps'],['Kokuo','Boiling steam bursts and horn charges'],['Saiken','Corrosive bubbles and slime traps'],['Chomei','Wing gusts and aerial dives'],['Gyuki','Tentacle sweeps and ink blasts'],['Kurama','Chakra roar and giant tailed-beast waves']];
function showBijuuCollection(){modalOpen=true;modal.classList.add('open');modal.innerHTML=`<div class="modal-card progression-modal"><p class="eyebrow">OPTIONAL SUPER-BOSS ARENAS</p><h2>BIJUU CARDS</h2><p>Cards are earned only by defeating their dedicated challenge. One primary card may be equipped. No Bijuu spins exist.</p><div class="reward-grid bijuu-grid">${BIJUU.map(([name,desc])=>`<button class="reward-card" data-bijuu="${name}"><strong>${saved.bijuuCards.includes(name)?'◆ ':'◇ '}${name}</strong><small>${desc}${saved.bijuuCards.includes(name)?' · CARD OWNED':' · Challenge undiscovered'}</small></button>`).join('')}</div><div class="modal-actions"><button data-action="progress">BACK</button></div></div>`;modal.querySelectorAll('[data-bijuu]').forEach(b=>b.onclick=()=>{const name=b.dataset.bijuu;if(saved.bijuuCards.includes(name)){saved.equippedBijuu=name;saveProgress();b.querySelector('strong').textContent=`◆ ${name} · EQUIPPED`}else{modal.innerHTML=`<div class="modal-card"><p class="eyebrow">SUPER-BOSS CHALLENGE</p><h2>${name.toUpperCase()}</h2><p>${BIJUU.find(x=>x[0]===name)[1]}. Dedicated arena challenge, multi-phase boss, high danger.</p><div class="modal-actions"><button data-action="enter">ENTER CHALLENGE</button><button data-action="bijuu-back">BACK</button></div></div>`;modal.querySelector('[data-action=enter]').onclick=()=>startBijuuBoss(name);modal.querySelector('[data-action=bijuu-back]').onclick=showBijuuCollection}});modal.querySelector('[data-action=progress]').onclick=showProgression}
function startBijuuBoss(name){initRun();worldWidth=1500;roomName=`${name.toUpperCase()} ARENA`;enemies=[];const boss=makeEnemy('boss',850);boss.name=name.toUpperCase();boss.hp=boss.maxHp=1500;boss.w=150;boss.h=170;boss.damage=32;boss.speed=70;boss.range=190;boss.color='#b94f58';boss.type='bijuu';boss.phase=1;enemies.push(boss);message=`${name.toUpperCase()} AWAKENS`;messageTimer=3;}
function keyDown(e){if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Space'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.repeat)return;if(e.code==='KeyJ')input.attack=true;if(e.code==='KeyU')input.heavy=true;if(e.code==='Space'||e.code==='ArrowUp'||e.code==='KeyW')input.jump=true;if(e.code==='ShiftLeft'||e.code==='ShiftRight')input.dash=true;if(e.code==='KeyL')input.skill1=true;if(e.code==='KeyI')input.skill2=true;if(e.code==='Escape'&&screenMode==='play'){paused=!paused;showPause()}}
function keyUp(e){keys.delete(e.code)}
function showPause(){modalOpen=true;modal.classList.add('open');modal.innerHTML=`<div class="modal-card"><p class="eyebrow">BATTLE PAUSED</p><h2>TAKE A BREATH</h2><div class="modal-actions"><button data-action="resume">RESUME</button><button data-action="progress">SHINOBI RECORD</button><button data-action="home">TITLE</button></div></div>`;modal.querySelector('[data-action=resume]').onclick=()=>{paused=false;closeModal()};modal.querySelector('[data-action=progress]').onclick=showProgression;modal.querySelector('[data-action=home]').onclick=showTitle}
function touchSetup(){document.querySelectorAll('.touch').forEach(b=>{const action=b.dataset.action;b.addEventListener('pointerdown',e=>{e.preventDefault();b.classList.add('active');if(action==='block')input.block=true;else input[action]=true});const up=e=>{e.preventDefault();b.classList.remove('active');if(action==='block')input.block=false};b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('pointerleave',up)});const zone=document.querySelector('#stick-zone'),knob=document.querySelector('#stick-knob');if(zone){zone.addEventListener('pointerdown',e=>{zone.setPointerCapture(e.pointerId);updateStick(e)});zone.addEventListener('pointermove',e=>{if(e.buttons)updateStick(e)});zone.addEventListener('pointerup',()=>{input.move=0;knob.style.transform='translate(0,0)'})}function updateStick(e){const r=zone.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2);input.move=clamp(dx/(r.width*.42),-1,1);knob.style.transform=`translate(${input.move*28}px,0)`}}
document.querySelector('#start-run').addEventListener('click',initRun);document.querySelector('#open-spins').addEventListener('click',()=>showSpinMenu());document.querySelector('#open-progression').addEventListener('click',showProgression);document.querySelector('#open-controls').addEventListener('click',()=>{modalOpen=true;modal.classList.add('open');modal.innerHTML=`<div class="modal-card"><p class="eyebrow">FIELD MANUAL</p><h2>CONTROLS</h2><p>Move A/D or arrows · Jump Space/W · Strike J · Heavy U · Dash Shift · Guard K · Jutsu L/I. Touch controls available on mobile.</p><div class="modal-actions"><button data-action="close">BACK</button></div></div>`;modal.querySelector('[data-action=close]').onclick=closeModal});document.querySelector('#pause-button').addEventListener('click',()=>{if(screenMode==='play'){paused=true;showPause()}});window.addEventListener('keydown',keyDown);window.addEventListener('keyup',keyUp);touchSetup();modal.addEventListener('click',e=>{if(e.target.dataset.action==='close')closeModal()});
requestAnimationFrame(frame);
})();

